pub fn bidiClass(cp: u21) BidiClass {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        const r = ranges[mid];
        if (cp < r.start) {
            hi = mid;
        } else if (cp > r.end) {
            lo = mid + 1;
        } else {
            return r.class;
        }
    }
    for (unassigned_defaults) |r| {
        if (cp >= r.start and cp <= r.end) return r.class;
    }
    return .l_or_other;
}
